def maxDistToClosest(seats):
    n = len(seats)
    best = 0
    last = -1
    for i, s in enumerate(seats):
        if s == 1:
            if last == -1:
                best = i
            else:
                best = max(best, (i - last) // 2)
            last = i
    return max(best, n - 1 - last)
